begin;
set local search_path=public,extensions;
select plan(20);
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values
('a1511111-1111-4111-8111-111111111111','authenticated','authenticated','lifecycle-a@local.test','{}','{}'),
('a1522222-2222-4222-8222-222222222222','authenticated','authenticated','lifecycle-b@local.test','{}','{}');
select set_config('request.jwt.claim.sub','a1511111-1111-4111-8111-111111111111',true);
set local role authenticated;
select throws_ok($$select public.request_account_deletion('no')$$,'22023',null,'Explicit confirmation required');
select throws_ok($$insert into storage.objects(bucket_id,name) values('progress-photos','a1511111-1111-4111-8111-111111111111/a.jpg')$$,'42501',null,'Direct upload cannot bypass reservation');
select lives_ok($$select public.reserve_progress_upload('a1511111-1111-4111-8111-111111111111/a.jpg')$$,'Own reservation allowed');
select lives_ok($$select public.reserve_progress_upload('a1511111-1111-4111-8111-111111111111/a.jpg')$$,'Same reservation idempotent');
select throws_ok($$select public.reserve_progress_upload('a1522222-2222-4222-8222-222222222222/a.jpg')$$,'22023',null,'Cross-owner path blocked');
select throws_ok($$select public.reserve_progress_upload('a1511111-1111-4111-8111-111111111111/../a.jpg')$$,'22023',null,'Traversal blocked');
select lives_ok($$insert into storage.objects(bucket_id,name) values('progress-photos','a1511111-1111-4111-8111-111111111111/a.jpg')$$,'Reserved upload allowed');
select ok(not has_table_privilege('authenticated','private.mutation_receipts','SELECT'),'Receipts private');
select ok(not has_function_privilege('authenticated','public.claim_account_deletions(integer)','EXECUTE'),'Client cannot claim deletion work');
select ok(not has_function_privilege('authenticated','public.reserve_food_upload(uuid,text)','EXECUTE'),'Client cannot reserve another food owner');
reset role;
select public.reserve_progress_upload('a1511111-1111-4111-8111-111111111111/'||gen_random_uuid()::text||'.jpg') from generate_series(1,49);
select throws_ok($$select public.reserve_progress_upload('a1511111-1111-4111-8111-111111111111/b.jpg')$$,'54000',null,'50-slot progress quota enforced');
select public.reserve_food_upload('a1511111-1111-4111-8111-111111111111','a1511111-1111-4111-8111-111111111111/'||gen_random_uuid()::text||'.jpg') from generate_series(1,10);
select throws_ok($$select public.reserve_food_upload('a1511111-1111-4111-8111-111111111111','a1511111-1111-4111-8111-111111111111/b.jpg')$$,'54000',null,'10-slot food quota enforced');
set local role authenticated;
select lives_ok($$select public.request_account_deletion('DELETE MY ACCOUNT')$$,'Owner may request deletion');
select lives_ok($$select public.request_account_deletion('DELETE MY ACCOUNT')$$,'Deletion request idempotent');
select throws_ok($$insert into public.water_logs(user_id,amount_ml) values('a1511111-1111-4111-8111-111111111111',250)$$,'42501',null,'Writes frozen');
select throws_ok($$select public.reserve_progress_upload('a1511111-1111-4111-8111-111111111111/b.jpg')$$,'42501',null,'Uploads frozen');
reset role;
select is((select count(*)::int from private.account_deletions where user_id='a1511111-1111-4111-8111-111111111111'),1,'Only one fixture queued');
select ok((select ready_at>clock_timestamp() from private.account_deletions where user_id='a1511111-1111-4111-8111-111111111111'),'Drain grace prevents premature deletion');
select set_config('request.jwt.claim.sub','a1522222-2222-4222-8222-222222222222',true);
set local role authenticated;
select lives_ok($$insert into public.water_logs(user_id,amount_ml) values('a1522222-2222-4222-8222-222222222222',250)$$,'Other account unaffected');
reset role;
select ok(not public.account_deletion_ready('a1511111-1111-4111-8111-111111111111',gen_random_uuid()),'Invalid lease cannot authorize deletion');
select * from finish();
rollback;
